-- Eintraege aus oeffentlichen Quellen fuers Problembrett.
-- ERZEUGT aus web/src/features/connect/publicSourceProblems.ts mit
-- `npm run public-problems:sql`. Nicht von Hand aendern, sondern die Liste.
-- Voraussetzung: Migration 20270111120000_problem_public_source.sql ist angewendet.
-- Wiederholbar: ein zweiter Lauf aktualisiert die Eintraege.
begin;

insert into public.network_problems (
  author_user_id, title, description, author_intent, locations, geographic_scope, topics, industries,
  status, published_at, origin, seed_key, source_name, source_url, source_year, source_note
) values
  (null, 'Menschen gehen zum Amt, weil es den Antrag nicht online gibt', 'Wer 2025 persönlich zur Behörde ging, tat das laut Befragung zu 66 %, weil es den Antrag nicht online gab oder Anwesenheit vorgeschrieben war. 12 % von ihnen hatten es online versucht und waren an technischen Problemen gescheitert.', 'observation', array[]::text[], 'germany', array['Verwaltung', 'Digitalisierung', 'Behördengang']::text[], array['Öffentliche Verwaltung']::text[], 'active', now() - interval '30 days' - interval '0 minutes', 'public_source', 'bitkom-verwaltung-2025-amt', 'Bitkom Research im Auftrag von Bitkom', 'https://www.bitkom.org/Presse/Presseinformation/Bitkom-Analyse-60-Prozent-der-Verwaltungsleistungen-sind-online-verfuegbar', '2025', 'Verbandsumfrage, Telefonbefragung, 1.005 Personen ab 18'),
  (null, 'Dieselben Angaben müssen bei jeder Behörde neu gemacht werden', '71 % der Befragten befürworteten 2025 mehr Datenaustausch zwischen Behörden, damit sie dieselben Angaben nicht immer wieder machen müssen.', 'observation', array[]::text[], 'germany', array['Verwaltung', 'Datenaustausch']::text[], array['Öffentliche Verwaltung']::text[], 'active', now() - interval '30 days' - interval '1 minutes', 'public_source', 'bitkom-verwaltung-2025-angaben', 'Bitkom Research im Auftrag von Bitkom', 'https://www.bitkom.org/Presse/Presseinformation/Bitkom-Analyse-60-Prozent-der-Verwaltungsleistungen-sind-online-verfuegbar', '2025', 'Verbandsumfrage, Telefonbefragung, 1.005 Personen ab 18'),
  (null, 'Bei Anträgen sieht niemand, wie weit die Bearbeitung ist', '85 % der Befragten wünschten 2025, jederzeit Bearbeitungsstand und voraussichtliche Restdauer eines Antrags zu sehen. Ebenfalls 85 % beklagten, Behörden bräuchten grundsätzlich zu lange.', 'observation', array[]::text[], 'germany', array['Verwaltung', 'Transparenz']::text[], array['Öffentliche Verwaltung']::text[], 'active', now() - interval '30 days' - interval '2 minutes', 'public_source', 'bitkom-verwaltung-2025-stand', 'Bitkom Research im Auftrag von Bitkom', 'https://www.bitkom.org/Presse/Presseinformation/Bitkom-Analyse-60-Prozent-der-Verwaltungsleistungen-sind-online-verfuegbar', '2025', 'Verbandsumfrage, Telefonbefragung, 1.005 Personen ab 18'),
  (null, 'Viele Verwaltungsleistungen gibt es noch nirgends digital', 'Von 579 untersuchten Verwaltungsleistungen waren 2025 laut Bitkom 230 noch nirgends digital verfügbar und nur 165 bundesweit umgesetzt. Ob ein Anliegen online geht, kann daher vom Wohnort abhängen.', 'observation', array[]::text[], 'germany', array['Verwaltung', 'OZG', 'Digitalisierung']::text[], array['Öffentliche Verwaltung']::text[], 'active', now() - interval '30 days' - interval '3 minutes', 'public_source', 'bitkom-ozg-2025-digital', 'Bitkom', 'https://www.bitkom.org/Presse/Presseinformation/Bitkom-Analyse-60-Prozent-der-Verwaltungsleistungen-sind-online-verfuegbar', '2025', 'Analyse des Branchenverbands zur Umsetzung des Onlinezugangsgesetzes'),
  (null, 'Schulen haben schlechtes oder gar kein WLAN', '87 % der befragten Schülerinnen und Schüler nannten 2023 schlechtes oder fehlendes WLAN als dringlichstes Problem ihrer Schule, noch vor dem Lehrkräftemangel (59 %).', 'observation', array[]::text[], 'germany', array['Schule', 'WLAN', 'Digitalisierung']::text[], array['Bildung']::text[], 'active', now() - interval '30 days' - interval '4 minutes', 'public_source', 'bitkom-schueler-2023-wlan', 'Bitkom Research im Auftrag von Bitkom', 'https://www.bitkom.org/Presse/Presseinformation/Schueler-wollen-digitaler-lernen', '2023', 'Verbandsumfrage, Telefonbefragung, 504 Schülerinnen und Schüler (14 bis 19)'),
  (null, 'Betriebe finden keine Nachfolge', 'Rund 5.620 Betrieben, die 2024 in der IHK-Beratung eine Nachfolge suchten, stand kein Interessent gegenüber. 72 % der abgabewilligen Inhaber wollen aus Altersgründen aufhören.', 'observation', array[]::text[], 'germany', array['Nachfolge', 'Mittelstand']::text[], array['KMU']::text[], 'active', now() - interval '30 days' - interval '5 minutes', 'public_source', 'dihk-nachfolge-2025', 'DIHK, Unternehmensnachfolge-Report', 'https://www.dihk.de/de/newsroom/unternehmensnachfolge-report-2025-157794', '2025', 'Kammerauswertung der IHK-Beratungen, Datenjahr 2024'),
  (null, 'Ausbildungsplätze bleiben leer', '48 % der befragten Betriebe konnten 2025 nicht alle angebotenen Ausbildungsplätze besetzen. 26 % boten weniger Plätze an als im Vorjahr, 15 % mehr.', 'observation', array[]::text[], 'germany', array['Ausbildung', 'Nachwuchs']::text[], array['KMU', 'Bildung']::text[], 'active', now() - interval '30 days' - interval '6 minutes', 'public_source', 'dihk-ausbildung-2025', 'DIHK, Ausbildungsumfrage', 'https://www.dihk.de/de/newsroom/ausbildung-2025-viele-betriebe-vor-herausforderungen-157708', '2025', 'Kammerumfrage, Stichprobengröße nicht angegeben'),
  (null, 'Für die eigene Digitalisierung fehlt die Zeit', '60 % der befragten Unternehmen nannten 2025 fehlende Zeit oder Ressourcen als Hürde bei der Digitalisierung, 54 % empfanden sie als zu komplex und 42 % nannten die Kosten.', 'observation', array[]::text[], 'germany', array['Digitalisierung', 'Zeitmangel']::text[], array['KMU']::text[], 'active', now() - interval '30 days' - interval '7 minutes', 'public_source', 'dihk-digital-2025-zeit', 'DIHK, Digitalisierungsumfrage', 'https://www.dihk.de/de/newsroom/digitalisierung-2025-herausforderungen-und-fortschritte-fuer-unternehmen-157712', '2025', 'Kammerumfrage, Stichprobengröße nicht angegeben'),
  (null, 'Rechtsunsicherheit bremst die Nutzung der eigenen Daten', '62 % der befragten Unternehmen sahen 2025 rechtliche Unsicherheit als größte Bremse bei der Datennutzung.', 'observation', array[]::text[], 'germany', array['Daten', 'Recht', 'Digitalisierung']::text[], array['KMU']::text[], 'active', now() - interval '30 days' - interval '8 minutes', 'public_source', 'dihk-digital-2025-daten', 'DIHK, Digitalisierungsumfrage', 'https://www.dihk.de/de/newsroom/digitalisierung-2025-herausforderungen-und-fortschritte-fuer-unternehmen-157712', '2025', 'Kammerumfrage, Stichprobengröße nicht angegeben'),
  (null, 'Cybervorfälle treffen auch kleine Unternehmen', '18 % der kleinen und mittleren Unternehmen waren 2024 laut DIHK von einem erheblichen Cybervorfall betroffen. Nur 31 % der Betriebe führten 2025 regelmäßig Risikoanalysen durch.', 'observation', array[]::text[], 'germany', array['Cybersicherheit', 'KMU']::text[], array['KMU', 'IT']::text[], 'active', now() - interval '30 days' - interval '9 minutes', 'public_source', 'dihk-digital-2025-cyber', 'DIHK, Digitalisierungsumfrage', 'https://www.dihk.de/de/newsroom/digitalisierung-2025-herausforderungen-und-fortschritte-fuer-unternehmen-157712', '2025', 'Kammerumfrage, Stichprobengröße nicht angegeben'),
  (null, 'Im Handwerk bleiben Stellen und Ausbildungsplätze leer', 'Laut ZDH können im Handwerk über 250.000 Stellen und etwa 20.000 Ausbildungsplätze nicht besetzt werden. Die Verbandsseite nennt dazu kein Datum.', 'observation', array[]::text[], 'germany', array['Handwerk', 'Fachkräfte']::text[], array['Handwerk']::text[], 'active', now() - interval '30 days' - interval '10 minutes', 'public_source', 'zdh-handwerk-stellen', 'Zentralverband des Deutschen Handwerks', 'https://www.zdh.de/ueber-uns/fachbereich-arbeitsmarkt/tarifpolitik/fachkraefteeinwanderung/', 'ohne Datum', 'Eigenangabe des Verbands'),
  (null, 'Gründende kämpfen mit Kundengewinnung und Bürokratie', 'Laut KfW-Gründungsmonitor 2026 (Gründungen 2025) sorgen sich Gründende hauptsächlich um Kundengewinnung und Bürokratie, besonders im Nebenerwerb. Gesetzliche und regulatorische Pflichten kosten einige Stunden Wochenarbeitszeit.', 'observation', array[]::text[], 'germany', array['Gründen', 'Bürokratie', 'Kundengewinnung']::text[], array['Start-ups']::text[], 'active', now() - interval '30 days' - interval '11 minutes', 'public_source', 'kfw-gruendungsmonitor-2026', 'KfW Research, Gründungsmonitor', 'https://www.kfw.de/%C3%9Cber-die-KfW/KfW-Research/KfW-Gr%C3%BCndungsmonitor.html', '2026', 'Studie der Förderbank, Gründungen 2025'),
  (null, 'Vereinsvorstände verbringen viel Zeit mit Bürokratie', 'Über 77 % der 901 befragten ehrenamtlichen Leitungspersonen schätzten die Bürokratiebelastung für ihren Verein als hoch bis sehr hoch ein.', 'observation', array[]::text[], 'germany', array['Ehrenamt', 'Bürokratie']::text[], array['Vereine']::text[], 'active', now() - interval '30 days' - interval '12 minutes', 'public_source', 'dsee-buerokratie-2025', 'Deutsche Stiftung für Engagement und Ehrenamt', 'https://www.deutsche-stiftung-engagement-und-ehrenamt.de/pressemeldungen/dsee_umfrage_buerokratiebelastung_im_ehrenamt/', '2025', 'Befragung Dezember 2024 bis Januar 2025, 901 Leitungspersonen'),
  (null, 'Es gibt immer weniger landwirtschaftliche Betriebe', 'Die Zahl der landwirtschaftlichen Betriebe ging seit 2010 um rund 15 % zurück, das sind mehr als 44.000 Betriebe weniger (Bezug 2023).', 'observation', array[]::text[], 'germany', array['Landwirtschaft', 'Strukturwandel']::text[], array['Landwirtschaft']::text[], 'active', now() - interval '30 days' - interval '13 minutes', 'public_source', 'bmel-betriebe-2023', 'BMEL-Statistik, Betriebsstruktur und Entwicklung', 'https://www.bmel-statistik.de/landwirtschaft/landwirtschaftliche-betriebe/betriebsstruktur-und-entwicklung', '2023', 'Amtliche Statistik'),
  (null, 'Nachts hören Millionen Menschen Verkehrslärm', 'Nach der Lärmkartierung 2022 waren in Deutschland rund 14,9 Millionen Menschen nachts Verkehrslärm über 50 dB(A) ausgesetzt, ganztägig über 55 dB(A) rund 21,9 Millionen.', 'observation', array[]::text[], 'germany', array['Lärm', 'Wohnen', 'Mobilität']::text[], array['Verkehr']::text[], 'active', now() - interval '30 days' - interval '14 minutes', 'public_source', 'uba-laerm-2022', 'Umweltbundesamt, Belastung der Bevölkerung durch Verkehrslärm', 'https://www.umweltbundesamt.de/daten/umweltindikatoren/indikator-belastung-der-bevoelkerung-durch', '2022', 'Amtliche Lärmkartierung'),
  (null, 'Fernzüge kommen oft zu spät', 'Im ersten Halbjahr 2026 lag die Pünktlichkeit im Fernverkehr der Deutschen Bahn bei 58,7 %, die Reisendenpünktlichkeit bei 63,2 %.', 'observation', array[]::text[], 'germany', array['Bahn', 'Pünktlichkeit']::text[], array['Verkehr']::text[], 'active', now() - interval '30 days' - interval '15 minutes', 'public_source', 'db-fernverkehr-2026-h1', 'Deutsche Bahn, Konzern-Zwischenbericht (1. Halbjahr)', 'https://zbir.deutschebahn.com/2026/de/konzern-zwischenlagebericht-ungeprueft/qualitaet/puenktlichkeit/', '2026', 'Eigenangabe des Unternehmens, ungeprüft'),
  (null, 'Auf dem Land geht ohne Auto wenig', 'In ländlichen Räumen entfallen laut Mobilität in Deutschland mehr als 60 % der Wege auf das Auto und andere motorisierte Individualverkehrsmittel. Bundesweit werden knapp drei Viertel aller Kilometer so zurückgelegt.', 'observation', array[]::text[], 'germany', array['Mobilität', 'ländlicher Raum']::text[], array['Verkehr']::text[], 'active', now() - interval '30 days' - interval '16 minutes', 'public_source', 'bmv-mid-2023-land', 'Bundesverkehrsministerium, Mobilität in Deutschland (MiD)', 'https://www.bmv.de/SharedDocs/DE/Artikel/G/mobilitaet-in-deutschland.html', '2023', 'Haushaltsbefragung, Mai 2023 bis Juni 2024'),
  (null, 'Die Hälfte der Menschen in der EU nutzt keinen öffentlichen Verkehr', '2024 nutzten 50,6 % der Menschen ab 16 Jahren in der EU keinen öffentlichen Verkehr. Täglich nutzten ihn 10,7 %.', 'observation', array[]::text[], 'europe', array['ÖPNV', 'Mobilität']::text[], array['Verkehr']::text[], 'active', now() - interval '30 days' - interval '17 minutes', 'public_source', 'eurostat-oepnv-2024', 'Eurostat', 'https://ec.europa.eu/eurostat/web/products-eurostat-news/w/ddn-20260311-2', '2024', 'Amtliche Statistik'),
  (null, 'Haushalte werfen viel Essen weg', 'EU-Haushalte verursachten 2024 durchschnittlich 69 kg Lebensmittelabfälle pro Person, 53 % aller Lebensmittelabfälle. In der Herstellung kamen 25 kg, in der Primärproduktion 10 kg pro Person hinzu.', 'observation', array[]::text[], 'europe', array['Lebensmittel', 'Abfall']::text[], array['Lebensmittel']::text[], 'active', now() - interval '30 days' - interval '18 minutes', 'public_source', 'eurostat-lebensmittel-2024', 'Eurostat, Lebensmittelabfälle', 'https://ec.europa.eu/eurostat/statistics-explained/index.php?title=Food_waste_and_food_waste_prevention_-_estimates', '2024', 'Amtliche Statistik'),
  (null, 'Defekte Aufzüge und Rolltreppen treffen Menschen mit Beeinträchtigung stärker', 'Laut Inklusionsbarometer Mobilität sind nicht funktionierende Aufzüge und Rolltreppen für Menschen mit Beeinträchtigung ein signifikant größeres Problem als für andere (28 % zu 17 %).', 'observation', array[]::text[], 'germany', array['Barrierefreiheit', 'Mobilität']::text[], array['Mobilität']::text[], 'active', now() - interval '30 days' - interval '19 minutes', 'public_source', 'aktion-mensch-aufzuege', 'Aktion Mensch, Inklusionsbarometer Mobilität', 'https://www.aktion-mensch.de/inklusion/studien/studie-inklusionsbarometer-mobilitaet', 'ohne Jahresangabe', 'Studie eines Sozialverbands; die Zuordnung der Zahlen ergibt sich aus der Überschrift'),
  (null, 'Medizinische Versorgung scheitert für manche an Kosten, Entfernung oder Wartezeit', '2024 hatten 3,8 % der Menschen ab 16 in der EU einen ungedeckten medizinischen Bedarf, bei 2,5 % lag es an Kosten, Entfernung oder Wartelisten.', 'observation', array[]::text[], 'europe', array['Gesundheit', 'Zugang']::text[], array['Gesundheitswesen']::text[], 'active', now() - interval '30 days' - interval '20 minutes', 'public_source', 'eurostat-versorgung-2024', 'Eurostat, ungedeckter Versorgungsbedarf', 'https://ec.europa.eu/eurostat/statistics-explained/index.php?title=Unmet_health_care_needs_statistics', '2024', 'Amtliche Statistik')
on conflict (seed_key) where seed_key is not null do update set
  title = excluded.title,
  description = excluded.description,
  locations = excluded.locations,
  geographic_scope = excluded.geographic_scope,
  topics = excluded.topics,
  industries = excluded.industries,
  source_name = excluded.source_name,
  source_url = excluded.source_url,
  source_year = excluded.source_year,
  source_note = excluded.source_note;

commit;
